#include <WiFi.h>
#include <WebServer.h>
#include "HX711.h"

// Configuración de pines
#define LOADCELL_DOUT_PIN 21
#define LOADCELL_SCK_PIN 22

HX711 scale;
WebServer server;

const char* ssid = "your_SSID";
const char* password = "your_PASSWORD";

void setup() {
  Serial.begin(115200);
  scale.begin(LOADCELL_DOUT_PIN, LOADCELL_SCK_PIN);

  // Conectar a WiFi
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Conectando a WiFi...");
  }
  Serial.println("Conectado a WiFi");

  // Configurar servidor web
  server.on("/", handleRoot);
  server.on("/read", handleRead);
  server.begin();
}

void loop() {
  server.handleClient();
}

void handleRoot() {
  String html = "<html><body><h1>Medición de Masa y Fuerza</h1>";
  html += "<p><a href=\"/read\">Leer Masa</a></p>";
  html += "</body></html>";
  server.send(200, "text/html", html);
}

void handleRead() {
  float weight = scale.get_units(10); // Promediar 10 lecturas
  String response = "Masa: " + String(weight) + " g";
  server.send(200, "text/plain", response);
}

